(async () => {
  const root = document.querySelector('[data-window-gallery]');
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 8000));
  const stage = root.querySelector('[data-wg-stage]');
  const canvas = stage.querySelector('canvas');
  const cs = canvas ? getComputedStyle(canvas) : null;
  return {
    cls: root.className,
    stageBox: [Math.round(stage.clientWidth), Math.round(stage.clientHeight)],
    canvasAttr: canvas ? [canvas.width, canvas.height] : null,
    canvasCss: cs ? [cs.width, cs.height] : null,
    swatchesInPanel: root.querySelectorAll('.wg__panel .wg__swatch').length,
    swatchText: [...root.querySelectorAll('.wg__swatch-label')].map(e => e.textContent).slice(0, 7)
  };
})()
